"""Stock levels: on hand, reserved for orders, and available."""


class Inventory:
    def __init__(self):
        self._on_hand: dict[str, int] = {}
        self._reserved: dict[str, int] = {}

    def receive(self, sku: str, qty: int) -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._on_hand[sku] = self._on_hand.get(sku, 0) + qty

    def on_hand(self, sku: str) -> int:
        return self._on_hand.get(sku, 0)

    def reserved(self, sku: str) -> int:
        return self._reserved.get(sku, 0)

    def available(self, sku: str) -> int:
        return self.on_hand(sku) - self.reserved(sku)

    def reserve(self, sku: str, qty: int) -> None:
        """Reserve `qty` available units for an order."""
        if qty <= 0:
            raise ValueError("qty must be positive")
        if qty > self.available(sku):
            raise ValueError(f"only {self.available(sku)} of {sku} available")
        self._reserved[sku] = self.reserved(sku) + qty

    def release(self, sku: str, qty: int) -> None:
        """Give `qty` reserved units back to available.

        `qty` must be positive. Releasing more than is currently reserved for
        the SKU (including a SKU with nothing reserved) raises ValueError and
        changes nothing.
        """
        raise NotImplementedError

    def ship(self, sku: str, qty: int) -> None:
        """Ship `qty` reserved units: they leave both reserved and on hand."""
        if qty <= 0:
            raise ValueError("qty must be positive")
        if qty > self.reserved(sku):
            raise ValueError(f"only {self.reserved(sku)} of {sku} reserved")
        self._reserved[sku] -= qty
        self._on_hand[sku] -= qty
"""Shopping cart."""

from dataclasses import dataclass


@dataclass
class Line:
    sku: str
    unit_price_cents: int
    qty: int


class Cart:
    def __init__(self):
        self._lines: dict[str, Line] = {}

    def add(self, sku: str, unit_price_cents: int, qty: int = 1) -> None:
        """Add `qty` units. Adding a SKU already in the cart increases its quantity."""
        if qty <= 0:
            raise ValueError("qty must be positive")
        if unit_price_cents < 0:
            raise ValueError("price must not be negative")
        if sku in self._lines:
            self._lines[sku].qty += qty
        else:
            self._lines[sku] = Line(sku, unit_price_cents, qty)

    def remove(self, sku: str) -> None:
        if sku not in self._lines:
            raise ValueError(f"{sku} is not in the cart")
        del self._lines[sku]

    def lines(self) -> list[Line]:
        return sorted(self._lines.values(), key=lambda line: line.sku)

    def line_total(self, sku: str) -> int:
        """Total for one line in cents."""
        if sku not in self._lines:
            raise ValueError(f"{sku} is not in the cart")
        line = self._lines[sku]
        return line.unit_price_cents * line.qty

    def subtotal(self) -> int:
        """Sum of all line totals in cents."""
        return sum(self.line_total(sku) for sku in self._lines)
"""Coupons. See docs/discounts.md."""

from dataclasses import dataclass
from datetime import date

from .money import percent_of


@dataclass(frozen=True)
class Coupon:
    code: str
    kind: str  # "percent" or "fixed"
    value: int  # percent points, or cents
    expires: date | None = None
    min_subtotal_cents: int = 0


def apply_coupon(subtotal_cents: int, coupon: Coupon) -> int:
    """Apply one coupon, ignoring expiry and minimum. Never returns less than 0."""
    if subtotal_cents < 0:
        raise ValueError("subtotal must not be negative")
    if coupon.kind == "percent":
        total = subtotal_cents - percent_of(subtotal_cents, coupon.value)
    elif coupon.kind == "fixed":
        total = subtotal_cents - coupon.value
    else:
        raise ValueError(f"unknown coupon kind {coupon.kind!r}")
    return max(total, 0)


